//! C-Compatible Tensor Runtime Functions
//!
//! This module provides C-compatible Rust functions for tensor operations
//! that can be called from assembly code generated by the native backend.
//!
//! Supports matrix multiplication, einsum, and reshape operations.

/// Matrix multiplication: C = A @ B
///
/// C signature: void sounio_tensor_matmul(
///     const double* A,    // RDI: M×K matrix (row-major)
///     const double* B,    // RSI: K×N matrix (row-major)
///     double* C,          // RDX: M×N output matrix (row-major)
///     int M,              // RCX: rows of A
///     int K,              // R8:  columns of A / rows of B
///     int N               // R9:  columns of B
/// )
#[unsafe(no_mangle)]
pub unsafe extern "C" fn sounio_tensor_matmul(
    a: *const f64,
    b: *const f64,
    c: *mut f64,
    m: i32,
    k: i32,
    n: i32,
) {
    if a.is_null() || b.is_null() || c.is_null() || m <= 0 || k <= 0 || n <= 0 {
        return;
    }

    let m = m as usize;
    let k = k as usize;
    let n = n as usize;

    let a_slice = unsafe { std::slice::from_raw_parts(a, m * k) };
    let b_slice = unsafe { std::slice::from_raw_parts(b, k * n) };
    let c_slice = unsafe { std::slice::from_raw_parts_mut(c, m * n) };

    // Initialize output to zero
    for i in 0..(m * n) {
        c_slice[i] = 0.0;
    }

    // Standard matrix multiplication: C[i,j] = sum_l A[i,l] * B[l,j]
    for i in 0..m {
        for j in 0..n {
            let mut sum = 0.0;
            for l in 0..k {
                sum += a_slice[i * k + l] * b_slice[l * n + j];
            }
            c_slice[i * n + j] = sum;
        }
    }
}

